    """ return a boolean if we WILL be using numexpr """
    if op_str is not None:

        # required min elements (otherwise we are adding overhead)
        if np.prod(a.shape) > _MIN_ELEMENTS:

            # check for dtype compatibility
            dtypes = set()
            for o in [a, b]:
                if hasattr(o, "dtypes"):
                    s = o.dtypes.value_counts(dropna=False)  # Using dropna=False to properly account for NaNs
                    if len(s) > 1:
                        return False
                    dtypes |= {s.index.astype(str)[0]}  # Ensure only unique dtypes are collected
                elif isinstance(o, np.ndarray):
                    dtypes |= {o.dtype.name}
                else:
                    # Unsupported type
                    return False

            # allowed are a superset
            if not len(dtypes):
                return False  # No dtypes found

            if _ALLOWED_DTYPES[dtype_check] >= dtypes:
                return True

    return False
