def _can_use_numexpr(op, op_str, a, b, dtype_check):
    """ return a boolean if we WILL be using numexpr """
    if op_str is not None:

        # required min elements (otherwise we are adding overhead)
        if np.prod(a.shape) > _MIN_ELEMENTS:

            # check for dtype compatibility
            dtypes = set()
            for o in [a, b]:
                if hasattr(o, "dtypes"):
                    s = o.dtypes.value_counts()
                    if len(s) > 1:
                        return False
                    dtypes |= {s.index.astype(str)[0]}  # Use the first dtype, as there should be only one type
                elif isinstance(o, np.ndarray):
                    dtypes |= {o.dtype.name}
                # Add handling for float values & other cases where 'o' might not have 'dtypes'
                elif np.issubdtype(type(o), np.number):  
                    dtypes |= {type(o).__name__}  
                else:
                    raise TypeError(f"Unsupported type: {type(o)}")

            # allowed are a superset
            if not len(dtypes):
                return False  # No dtypes found

            if _ALLOWED_DTYPES[dtype_check] >= dtypes:
                return True

    return False
