            # check for dtype compatibility
            dtypes = set()
            for o in [a, b]:
                if hasattr(o, "dtypes"):
                    if isinstance(o, pd.DataFrame):
                        s = o.dtypes.value_counts()
                    else:
                        s = pd.Series(o).dtype.value_counts()

                    if len(s) > 1:
                        return False

                    dtypes |= {s.index.astype(str)[0]}  # Use the first dtype
                elif isinstance(o, np.ndarray):
                    dtypes |= {o.dtype.name}
                else:
                    raise TypeError(f"Unsupported type: {type(o)}")

            # allowed are a superset
            if not len(dtypes):
                return False  # No dtypes found

            if _ALLOWED_DTYPES[dtype_check] >= dtypes:
                return True

    return False
